CONTACT_PEAK_IOU = 0.363
CONTACT_MEAN_IOU = 0.132

#: The last frame P3 still overlapped the cart at LINK_DRIFT_IOU or better.
LAST_CONTACT_FRAME = 124

#: The frame P3 left the frame for good. The cart is in frame throughout.
OWNER_GONE_FRAME = 164


